package app.kinnect.live;
import android.content.Context;
import android.os.*;
import java.util.*;
import org.json.*;
import org.webrtc.*;
/** Camera, microphone, rendering and peer connections all run in native WebRTC. */
final class NativeRtc {
 interface Events { default void connection(String state){} void signal(String peer,JSONObject value);void status(String message);}
 private static boolean initialized;
 private final Handler main=new Handler(Looper.getMainLooper());
 private final Events events;private final EglBase egl;private final PeerConnectionFactory factory;
 private final Map<String,PeerConnection> peers=new HashMap<>();private final Map<String,List<IceCandidate>> candidates=new HashMap<>();
 private final List<PeerConnection.IceServer> servers=new ArrayList<>();
 private final SurfaceViewRenderer local,remote;private VideoCapturer camera;private SurfaceTextureHelper helper;
 private LiveEffects effects;LiveEffects effects(){return effects;}private VideoSource videoSource;private VideoTrack video;private AudioSource audioSource;private AudioTrack audio;private boolean closed;
 NativeRtc(Context context,JSONObject config,SurfaceViewRenderer local,SurfaceViewRenderer remote,Events events){this.events=events;this.local=local;this.remote=remote;
 synchronized(NativeRtc.class){if(!initialized){PeerConnectionFactory.initialize(PeerConnectionFactory.InitializationOptions.builder(context.getApplicationContext()).createInitializationOptions());initialized=true;}}
 egl=EglBase.create();factory=PeerConnectionFactory.builder().setVideoEncoderFactory(new DefaultVideoEncoderFactory(egl.getEglBaseContext(),true,true)).setVideoDecoderFactory(new DefaultVideoDecoderFactory(egl.getEglBaseContext())).createPeerConnectionFactory();
 if(local!=null){local.init(egl.getEglBaseContext(),null);local.setMirror(true);local.setScalingType(RendererCommon.ScalingType.SCALE_ASPECT_FIT);}
 if(remote!=null){remote.init(egl.getEglBaseContext(),null);remote.setScalingType(RendererCommon.ScalingType.SCALE_ASPECT_FIT);}
 JSONArray rows=config.optJSONArray("iceServers");for(int i=0;rows!=null&&i<rows.length();i++){JSONObject item=rows.optJSONObject(i);Object urls=item.opt("urls");List<String> list=new ArrayList<>();if(urls instanceof JSONArray){JSONArray a=(JSONArray)urls;for(int j=0;j<a.length();j++)list.add(a.optString(j));}else if(urls instanceof String)list.add((String)urls);if(!list.isEmpty())servers.add(PeerConnection.IceServer.builder(list).setUsername(item.optString("username")).setPassword(item.optString("credential")).createIceServer());}
 }
 void framing(boolean full){for(SurfaceViewRenderer view:new SurfaceViewRenderer[]{local,remote})if(view!=null){view.setEnableHardwareScaler(false);view.setScalingType(full?RendererCommon.ScalingType.SCALE_ASPECT_FIT:RendererCommon.ScalingType.SCALE_ASPECT_FILL);}}
 void media(Context context,boolean withVideo){audioSource=factory.createAudioSource(new MediaConstraints());audio=factory.createAudioTrack("kinnect-audio",audioSource);if(!withVideo)return;Camera2Enumerator devices=new Camera2Enumerator(context);String chosen=null;for(String name:devices.getDeviceNames()){if(chosen==null||devices.isFrontFacing(name))chosen=name;if(devices.isFrontFacing(name))break;}if(chosen==null)throw new IllegalStateException(I18n.t("Không tìm thấy camera."));camera=devices.createCapturer(chosen,null);if(camera==null)throw new IllegalStateException(I18n.t("Không mở được camera."));helper=SurfaceTextureHelper.create("KinnectCamera",egl.getEglBaseContext());videoSource=factory.createVideoSource(false);effects=new LiveEffects();videoSource.setVideoProcessor(effects);camera.initialize(helper,context,videoSource.getCapturerObserver());camera.startCapture(1280,960,24);video=factory.createVideoTrack("kinnect-video",videoSource);if(local!=null)video.addSink(local);}
 private void ui(Runnable task){main.post(()->{if(!closed)task.run();});}
 private void error(String text){ui(()->events.status(text));}
 private PeerConnection peer(final String id){if(peers.containsKey(id))return peers.get(id);PeerConnection.RTCConfiguration config=new PeerConnection.RTCConfiguration(servers);config.sdpSemantics=PeerConnection.SdpSemantics.UNIFIED_PLAN;PeerConnection pc=factory.createPeerConnection(config,new PeerConnection.Observer(){
 public void onSignalingChange(PeerConnection.SignalingState s){} public void onIceConnectionReceivingChange(boolean receiving){} public void onIceGatheringChange(PeerConnection.IceGatheringState s){} public void onIceCandidatesRemoved(IceCandidate[] rows){} public void onAddStream(MediaStream stream){} public void onRemoveStream(MediaStream stream){} public void onDataChannel(DataChannel channel){} public void onRenegotiationNeeded(){}
 public void onIceConnectionChange(PeerConnection.IceConnectionState s){ui(()->events.connection(s.name()));if(s==PeerConnection.IceConnectionState.CONNECTED||s==PeerConnection.IceConnectionState.COMPLETED)error(I18n.t("Đã kết nối"));if(s==PeerConnection.IceConnectionState.FAILED)error(I18n.t("Kết nối media thất bại. Hãy thử lại hoặc đổi mạng."));}
 public void onIceCandidate(IceCandidate c){ui(()->events.signal(id,NativeSocket.json("candidate",NativeSocket.json("candidate",c.sdp,"sdpMid",c.sdpMid,"sdpMLineIndex",c.sdpMLineIndex))));}
 public void onAddTrack(RtpReceiver receiver,MediaStream[] streams){MediaStreamTrack track=receiver.track();if(track instanceof VideoTrack&&remote!=null)((VideoTrack)track).addSink(remote);}
 });if(pc==null)throw new IllegalStateException(I18n.t("Không tạo được kết nối media."));if(audio!=null)pc.addTrack(audio,Collections.singletonList("kinnect"));if(video!=null)pc.addTrack(video,Collections.singletonList("kinnect"));peers.put(id,pc);candidates.put(id,new ArrayList<>());return pc;}
 private SdpObserver observer(Runnable success){return new SdpObserver(){public void onCreateSuccess(SessionDescription d){}public void onSetSuccess(){ui(success);}public void onCreateFailure(String error){NativeRtc.this.error(I18n.t("Không tạo được mô tả media."));}public void onSetFailure(String error){NativeRtc.this.error(I18n.t("Không thiết lập được kết nối media."));}};}
 private void describe(String id,boolean offer){describe(id,offer,false);}
 void restart(String id){if(!closed)describe(id,true,true);}
 private void describe(String id,boolean offer,boolean restart){PeerConnection pc=peer(id);MediaConstraints constraints=new MediaConstraints();if(restart)constraints.optional.add(new MediaConstraints.KeyValuePair("IceRestart","true"));constraints.mandatory.add(new MediaConstraints.KeyValuePair("OfferToReceiveAudio","true"));constraints.mandatory.add(new MediaConstraints.KeyValuePair("OfferToReceiveVideo","true"));SdpObserver created=new SdpObserver(){public void onCreateSuccess(SessionDescription description){ui(()->pc.setLocalDescription(observer(()->events.signal(id,NativeSocket.json("description",NativeSocket.json("type",description.type.canonicalForm(),"sdp",description.description)))),description));}public void onSetSuccess(){}public void onCreateFailure(String e){error(I18n.t("Không tạo được mô tả media."));}public void onSetFailure(String e){error(I18n.t("Không thiết lập được media."));}};if(offer)pc.createOffer(created,constraints);else pc.createAnswer(created,constraints);}
 void offer(String id){if(!closed)describe(id,true);}
 void signal(String id,JSONObject value){if(closed)return;PeerConnection pc=peer(id);JSONObject description=value.optJSONObject("description"),candidate=value.optJSONObject("candidate");if(description!=null){String type=description.optString("type");if(!type.equals("offer")&&!type.equals("answer"))return;pc.setRemoteDescription(observer(()->{for(IceCandidate c:candidates.get(id))pc.addIceCandidate(c);candidates.get(id).clear();if(type.equals("offer"))describe(id,false);}),new SessionDescription(SessionDescription.Type.fromCanonicalForm(type),description.optString("sdp")));}else if(candidate!=null){IceCandidate c=new IceCandidate(candidate.optString("sdpMid"),candidate.optInt("sdpMLineIndex"),candidate.optString("candidate"));if(pc.getRemoteDescription()==null)candidates.get(id).add(c);else pc.addIceCandidate(c);}}
 void remove(String id){PeerConnection pc=peers.remove(id);candidates.remove(id);if(pc!=null)pc.dispose();}
 void microphone(boolean enabled){if(audio!=null)audio.setEnabled(enabled);}void camera(boolean enabled){if(video!=null)video.setEnabled(enabled);}
 void flip(){if(camera instanceof CameraVideoCapturer)((CameraVideoCapturer)camera).switchCamera(null);}
 void close(){if(closed)return;closed=true;if(effects!=null)effects.close();main.removeCallbacksAndMessages(null);for(PeerConnection p:peers.values())p.dispose();peers.clear();if(camera!=null){try{camera.stopCapture();}catch(InterruptedException e){Thread.currentThread().interrupt();}camera.dispose();}if(video!=null)video.dispose();if(audio!=null)audio.dispose();if(videoSource!=null)videoSource.dispose();if(audioSource!=null)audioSource.dispose();if(helper!=null)helper.dispose();if(local!=null)local.release();if(remote!=null)remote.release();factory.dispose();egl.release();}
}
